SELECT s1.`c0` AS `a`, s1.`c1` AS `b`, s1.`c2` AS `g`, s1.`c3` AS `l` FROM (SELECT s2.`c0` AS `c0`, s2.`c1` AS `c1`, (CASE WHEN (s2.`c0` IS NULL) THEN CAST(NULL AS BIGINT) ELSE (CASE WHEN (s2.`c1` IS NULL) THEN CAST(NULL AS BIGINT) ELSE GREATEST(s2.`c0`, s2.`c1`) END) END) AS `c2`, LEAST(s2.`c0`, s2.`c1`) AS `c3` FROM (SELECT v.`c0` AS `c0`, v.`c1` AS `c1` FROM (VALUES (CAST(1 AS BIGINT), CAST(NULL AS BIGINT)), (CAST(1 AS BIGINT), CAST(5 AS BIGINT))) AS v(`c0`, `c1`)) AS s2) AS s1
